using System.Globalization;
using System.Text;
using Erewhon.Application.Common;

namespace Erewhon.Seed.Tests;

/// <summary>
/// The persisted state that JADE <c>InitialDataLoader.loadData</c> produces from <c>Erewhon/DataFiles</c>,
/// derived from the data files and the loader and transaction-agent rules
/// [Erewhon/ErewhonModelSchema.scm:L8427-8974], independently of the target loader.
/// </summary>
public sealed class ExpectedSeedModel
{
    /// <summary>Format of a GUID generated by the target (<c>Guid.ToString("B")</c>, lower case).</summary>
    public const string GeneratedGuidPattern =
        @"^\{[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\}$";

    /// <summary>
    /// The date the file dates are relative to: <c>offsetStartDate.setDate(01, 01, 2000)</c> in
    /// <c>loadData</c> [Erewhon/ErewhonModelSchema.scm:L8467-8470]. The loader shifts every file date
    /// by (current date − this date), so the shifted current date corresponds to this file date.
    /// </summary>
    public static readonly DateOnly OffsetStartDate = new(2000, 1, 1);

    private const string SolutionFileName = "ErewhonModern.sln";
    private const string LocationsFile = "Locations.txt";
    private const string AgentsFile = "Agents.txt";
    private const string ClientsFile = "Clients.txt";
    private const string CategoriesFile = "Categories.txt";
    private const string RetailItemsFile = "RetailItems.txt";
    private const string TenderItemsFile = "TenderItems.txt";
    private const string CategoryRatesFile = "CategoryRates.txt";
    private const string AgentRatesFile = "AgentRates.txt";
    private const string TendersFile = "Tenders.txt";
    private const string RetailSalesFile = "RetailSales.txt";

    // getNextToken: the $Null text, the token separator and the LineSkipDelimiter constant (L78-79, L2818).
    private const string NullToken = "null";
    private const char TokenSeparator = '\t';
    private const char Blank = ' ';
    private const char LineSkipDelimiter = '#';

    // Item files write "October 1 1999"; sale and tender files write "22 January 2000".
    private static readonly string[] DateFormats = ["MMMM d yyyy", "d MMMM yyyy"];
    private const string TimeFormat = "HH:mm:ss";

    private ExpectedSeedModel(
        IReadOnlyList<ExpectedCountry> countries,
        IReadOnlyList<ExpectedRegion> regions,
        IReadOnlyList<ExpectedParty> agents,
        IReadOnlyList<ExpectedParty> clients,
        IReadOnlyList<ExpectedCategory> categories,
        IReadOnlyList<ExpectedCategoryRate> categoryRates,
        IReadOnlyList<ExpectedAgentRate> agentRates,
        IReadOnlyList<ExpectedItem> retailItems,
        IReadOnlyList<ExpectedItem> tenderItems,
        IReadOnlyList<ExpectedTenderLine> tenderLines,
        IReadOnlyList<ExpectedRetailSale> retailSales,
        IReadOnlyList<ExpectedTenderSale> tenderSales,
        IReadOnlySet<string> closedItemGuids,
        IReadOnlySet<string> dueItemGuids,
        IReadOnlyDictionary<string, int> dataLineCounts)
    {
        Countries = countries;
        Regions = regions;
        Agents = agents;
        Clients = clients;
        Categories = categories;
        CategoryRates = categoryRates;
        AgentRates = agentRates;
        RetailItems = retailItems;
        TenderItems = tenderItems;
        TenderLines = tenderLines;
        PersistedTenders = tenderLines.Where(line => line.Persisted).ToList();
        RetailSales = retailSales;
        TenderSales = tenderSales;
        ClosedItemGuids = closedItemGuids;
        DueItemGuids = dueItemGuids;
        DataLineCounts = dataLineCounts;
    }

    /// <summary>The company <c>createCompany</c> builds from the locale-5129 strings [Erewhon/ErewhonModelSchema.scm:L7935-7943].</summary>
    public static ExpectedCompany Company { get; } = new(
        "Erewhon Investments Inc",
        new ExpectedAddress(
            Street: "Erewhon House",
            City: "Christchurch",
            Country: "New Zealand",
            Email: "discover@jadeworld.com",
            Fax: "(64) 3 555 1267",
            Phone: "(64) 3 555 4519",
            WebSite: "www.jadeworld.com"));

    /// <summary>Countries in first-appearance order in <c>Locations.txt</c>, each with its region names.</summary>
    public IReadOnlyList<ExpectedCountry> Countries { get; }

    /// <summary>Regions in <c>Locations.txt</c> order.</summary>
    public IReadOnlyList<ExpectedRegion> Regions { get; }

    /// <summary>Agents in <c>Agents.txt</c> order.</summary>
    public IReadOnlyList<ExpectedParty> Agents { get; }

    /// <summary>Clients in <c>Clients.txt</c> order.</summary>
    public IReadOnlyList<ExpectedParty> Clients { get; }

    /// <summary>Item categories in <c>Categories.txt</c> order.</summary>
    public IReadOnlyList<ExpectedCategory> Categories { get; }

    /// <summary>Category commission rates in <c>CategoryRates.txt</c> order.</summary>
    public IReadOnlyList<ExpectedCategoryRate> CategoryRates { get; }

    /// <summary>Agent-to-rate links in <c>AgentRates.txt</c> order.</summary>
    public IReadOnlyList<ExpectedAgentRate> AgentRates { get; }

    /// <summary>Retail items in <c>RetailItems.txt</c> order, code numbers 1 to the retail line count.</summary>
    public IReadOnlyList<ExpectedItem> RetailItems { get; }

    /// <summary>Tender items in <c>TenderItems.txt</c> order, code numbers following the retail items.</summary>
    public IReadOnlyList<ExpectedItem> TenderItems { get; }

    /// <summary>Every <c>Tenders.txt</c> line in file order, persisted or rejected.</summary>
    public IReadOnlyList<ExpectedTenderLine> TenderLines { get; }

    /// <summary>The <c>Tenders.txt</c> lines that persist, in file order.</summary>
    public IReadOnlyList<ExpectedTenderLine> PersistedTenders { get; }

    /// <summary>Retail sales in <c>RetailSales.txt</c> order, with their agent commission.</summary>
    public IReadOnlyList<ExpectedRetailSale> RetailSales { get; }

    /// <summary>Tender sales awarded by the post-load closure, in closure order.</summary>
    public IReadOnlyList<ExpectedTenderSale> TenderSales { get; }

    /// <summary>GUIDs of the tender items closed when the tenders load (file closure date before <see cref="OffsetStartDate"/>).</summary>
    public IReadOnlySet<string> ClosedItemGuids { get; }

    /// <summary>GUIDs of the tender items the post-load closure processes (file closure date on or before <see cref="OffsetStartDate"/>).</summary>
    public IReadOnlySet<string> DueItemGuids { get; }

    /// <summary>Number of non-skipped lines per data file, keyed by file name.</summary>
    public IReadOnlyDictionary<string, int> DataLineCounts { get; }

    /// <summary><c>Company.getNumberOfLocations</c>: each country plus its regions.</summary>
    public int NumberOfLocations => Countries.Sum(country => 1 + country.RegionNames.Count);

    /// <summary>Sum of the retail item prices.</summary>
    public decimal RetailPriceSum => RetailItems.Sum(item => item.Price);

    /// <summary>Sum of the tender item reserve prices.</summary>
    public decimal ReservePriceSum => TenderItems.Sum(item => item.Price);

    /// <summary>Sum of the retail sale prices.</summary>
    public decimal RetailSalePriceTotal => RetailSales.Sum(sale => sale.SalePrice);

    /// <summary>Sum of the retail sale agent commissions.</summary>
    public decimal RetailCommissionTotal => RetailSales.Sum(sale => sale.AgentCommission);

    /// <summary>Retail sales plus tender sales.</summary>
    public int SalesTotal => RetailSales.Count + TenderSales.Count;

    /// <summary>
    /// Returns the full path of <c>Erewhon/DataFiles</c>, found beside the directory above
    /// <see cref="AppContext.BaseDirectory"/> that holds <c>ErewhonModern.sln</c>.
    /// </summary>
    /// <exception cref="InvalidOperationException">No directory holds the solution, or the data directory does not exist.</exception>
    public static string FindDataDirectory()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, SolutionFileName)))
        {
            directory = directory.Parent;
        }

        if (directory is null)
        {
            throw new InvalidOperationException(
                $"No directory at or above '{AppContext.BaseDirectory}' contains {SolutionFileName}.");
        }

        var dataDirectory = Path.GetFullPath(Path.Combine(directory.FullName, "..", "Erewhon", "DataFiles"));
        if (!Directory.Exists(dataDirectory))
        {
            throw new InvalidOperationException($"The seed data directory '{dataDirectory}' does not exist.");
        }

        return dataDirectory;
    }

    /// <summary>
    /// Reads the ten data files in <paramref name="dataDirectory"/> in the <c>loadData</c> order and
    /// derives the persisted records, the tender closure and the totals.
    /// </summary>
    /// <param name="dataDirectory">The directory holding the seed data files and photos.</param>
    /// <returns>The expected seed model.</returns>
    /// <exception cref="InvalidOperationException">
    /// The directory does not exist, a line does not hold its file's token count or value formats, or a record
    /// breaks a loader or transaction-agent rule that this model checks as a precondition instead of simulating (D-53).
    /// </exception>
    public static ExpectedSeedModel Load(string dataDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(dataDirectory);
        if (!Directory.Exists(dataDirectory))
        {
            throw new InvalidOperationException($"The seed data directory '{dataDirectory}' does not exist.");
        }

        var lineCounts = new Dictionary<string, int>(StringComparer.Ordinal);

        var (countries, regions) = LoadLocations(ReadRecords(dataDirectory, LocationsFile, 2, lineCounts));
        var agents = LoadParties(ReadRecords(dataDirectory, AgentsFile, 8, lineCounts));
        var clients = LoadParties(ReadRecords(dataDirectory, ClientsFile, 8, lineCounts));
        var categories = LoadCategories(ReadRecords(dataDirectory, CategoriesFile, 3, lineCounts));

        // getNextCodeNumber per item: retail items first, then tender items (L8652, L8822).
        var references = new ItemReferences(agents, regions, categories);
        var retailItems = LoadItems(
            ReadRecords(dataDirectory, RetailItemsFile, 10, lineCounts), dataDirectory, isTender: false, firstCodeNumber: 1, references);
        var tenderItems = LoadItems(
            ReadRecords(dataDirectory, TenderItemsFile, 11, lineCounts), dataDirectory, isTender: true, firstCodeNumber: retailItems.Count + 1, references);
        EnsureDistinctItemGuids(retailItems.Concat(tenderItems));

        var categoryRates = LoadCategoryRates(ReadRecords(dataDirectory, CategoryRatesFile, 2, lineCounts), categories);
        var agentRates = LoadAgentRates(ReadRecords(dataDirectory, AgentRatesFile, 3, lineCounts), agents, categoryRates);

        // TenderTA.doValidate closed-item rejection: TenderItem.isClosed is closureDate < server date (L7208-7223).
        var closedItemGuids = tenderItems
            .Where(item => item.FileClosureDate < OffsetStartDate)
            .Select(item => item.Guid)
            .ToHashSet(StringComparer.Ordinal);
        var tenderLines = LoadTenders(
            ReadRecords(dataDirectory, TendersFile, 5, lineCounts), tenderItems, clients, closedItemGuids);

        var commissions = new CommissionCalculator(agentRates, categoryRates);
        var retailSales = LoadRetailSales(
            ReadRecords(dataDirectory, RetailSalesFile, 5, lineCounts), retailItems, clients, commissions);

        var (tenderSales, dueItemGuids) = CloseTenders(tenderItems, tenderLines, categories, commissions);

        return new ExpectedSeedModel(
            countries,
            regions,
            agents,
            clients,
            categories,
            categoryRates,
            agentRates,
            retailItems,
            tenderItems,
            tenderLines,
            retailSales,
            tenderSales,
            closedItemGuids,
            dueItemGuids,
            lineCounts);
    }

    // loadLocations: the country is created on its first appearance, then the region (L8547-8576).
    private static (IReadOnlyList<ExpectedCountry> Countries, IReadOnlyList<ExpectedRegion> Regions) LoadLocations(
        IReadOnlyList<DataRecord> records)
    {
        var countryNames = new List<string>();
        var regionNamesByCountry = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        var regions = new List<ExpectedRegion>();

        foreach (var record in records)
        {
            var countryName = record.Required(0);
            var regionName = record.Required(1);

            if (!regionNamesByCountry.TryGetValue(countryName, out var regionNames))
            {
                regionNames = [];
                regionNamesByCountry.Add(countryName, regionNames);
                countryNames.Add(countryName);
            }

            // RegionTA.doValidate: region name unique within its country (L12588-12631).
            if (regionNames.Contains(regionName, StringComparer.Ordinal))
            {
                throw record.Error($"region '{regionName}' already exists in country '{countryName}'");
            }

            regionNames.Add(regionName);
            regions.Add(new ExpectedRegion(countryName, regionName));
        }

        var countries = countryNames
            .Select(name => new ExpectedCountry(name, regionNamesByCountry[name]))
            .ToList();
        return (countries, regions);
    }

    // loadAgents and loadClients: name, street, city, country, email, fax, phone, website (L8206-8217, L8398-8409).
    private static IReadOnlyList<ExpectedParty> LoadParties(IReadOnlyList<DataRecord> records)
    {
        var parties = new List<ExpectedParty>();
        var names = new HashSet<string>(StringComparer.Ordinal);

        foreach (var record in records)
        {
            var name = record.Required(0);

            // AgentTA and ClientTA: the name is new on create (L10149-10204, L10551-10598).
            if (!names.Add(name))
            {
                throw record.Error($"name '{name}' already exists");
            }

            // AddressTA.doValidate: street, city, country, phone and email are required (L9797-9884).
            var address = new ExpectedAddress(
                Street: record.Required(1),
                City: record.Required(2),
                Country: record.Required(3),
                Email: record.Required(4),
                Fax: record.Optional(5),
                Phone: record.Required(6),
                WebSite: record.Optional(7));
            parties.Add(new ExpectedParty(name, address));
        }

        return parties;
    }

    // loadCategories: prefix, name, description (L8275-8277); ItemCategoryTA upper-cases the prefix.
    private static IReadOnlyList<ExpectedCategory> LoadCategories(IReadOnlyList<DataRecord> records)
    {
        var categories = new List<ExpectedCategory>();

        foreach (var record in records)
        {
            var category = new ExpectedCategory(
                Prefix: record.Required(0).ToUpperInvariant(),
                Name: record.Required(1),
                Description: record.Required(2));

            // ItemCategoryTA.doValidate: prefix of at least 4 characters, prefix and name unique (L11444-11504).
            if (category.Prefix.Length < 4)
            {
                throw record.Error($"category prefix '{category.Prefix}' is shorter than 4 characters");
            }

            if (categories.Exists(existing => existing.Prefix == category.Prefix || existing.Name == category.Name))
            {
                throw record.Error($"category '{category.Name}' or prefix '{category.Prefix}' already exists");
            }

            categories.Add(category);
        }

        return categories;
    }

    // loadRetailItems: guid, name, description, photo, price, listed date, agent, country, region, category (L8639-8648).
    // loadTenderItems: the same with the reserve as price and the closure date after the listed date (L8808-8818).
    private static IReadOnlyList<ExpectedItem> LoadItems(
        IReadOnlyList<DataRecord> records,
        string dataDirectory,
        bool isTender,
        int firstCodeNumber,
        ItemReferences references)
    {
        var items = new List<ExpectedItem>();
        var agentColumn = isTender ? 7 : 6;

        foreach (var record in records)
        {
            var photoFileName = record.Optional(3);
            var item = new ExpectedItem(
                Guid: record.Required(0),
                IsTender: isTender,
                CodeNumber: firstCodeNumber + items.Count,
                Name: record.Required(1),
                Description: record.Required(2),
                PhotoFileName: photoFileName,
                PhotoBytes: photoFileName is null ? null : File.ReadAllBytes(Path.Combine(dataDirectory, photoFileName)),
                Price: record.ReadDecimal(4),
                FileListedDate: record.ReadDate(5),
                FileClosureDate: isTender ? record.ReadDate(6) : null,
                AgentName: record.Required(agentColumn),
                CountryName: record.Required(agentColumn + 1),
                RegionName: record.Required(agentColumn + 2),
                CategoryName: record.Required(agentColumn + 3));

            references.EnsureResolved(record, item);

            // ItemTA.doValidate: price greater than 0 (L11804).
            if (item.Price <= 0m)
            {
                throw record.Error($"price {item.Price} is not greater than 0");
            }

            items.Add(item);
        }

        return items;
    }

    // RetailItemsByGUIDDict and TenderItemsByGUIDDict: one item per GUID.
    private static void EnsureDistinctItemGuids(IEnumerable<ExpectedItem> items)
    {
        var duplicate = items
            .GroupBy(item => item.Guid, StringComparer.Ordinal)
            .FirstOrDefault(group => group.Count() > 1);
        if (duplicate is not null)
        {
            throw new InvalidOperationException($"Item GUID {duplicate.Key} appears on more than one item line.");
        }
    }

    // loadCategoryRates: category name, percentage (L8334-8339); CommissionRateTA.doValidate (L10839-10883).
    private static IReadOnlyList<ExpectedCategoryRate> LoadCategoryRates(
        IReadOnlyList<DataRecord> records,
        IReadOnlyList<ExpectedCategory> categories)
    {
        var rates = new List<ExpectedCategoryRate>();

        foreach (var record in records)
        {
            var rate = new ExpectedCategoryRate(record.Required(0), record.ReadDecimal(1));

            if (!categories.Any(category => category.Name == rate.CategoryName))
            {
                throw record.Error($"category '{rate.CategoryName}' does not exist");
            }

            if (rate.Percentage <= 0m || rate.Percentage > 100m)
            {
                throw record.Error($"percentage {rate.Percentage} is not greater than 0 and at most 100");
            }

            if (rates.Contains(rate))
            {
                throw record.Error($"category '{rate.CategoryName}' already holds percentage {rate.Percentage}");
            }

            rates.Add(rate);
        }

        return rates;
    }

    // loadAgentRates: agent, category, percentage; the category's rate with that percentage gains the agent (L8136-8149).
    private static IReadOnlyList<ExpectedAgentRate> LoadAgentRates(
        IReadOnlyList<DataRecord> records,
        IReadOnlyList<ExpectedParty> agents,
        IReadOnlyList<ExpectedCategoryRate> categoryRates)
    {
        var links = new List<ExpectedAgentRate>();

        foreach (var record in records)
        {
            var link = new ExpectedAgentRate(record.Required(0), record.Required(1), record.ReadDecimal(2));

            if (!agents.Any(agent => agent.Name == link.AgentName))
            {
                throw record.Error($"agent '{link.AgentName}' does not exist");
            }

            if (!categoryRates.Contains(new ExpectedCategoryRate(link.CategoryName, link.Percentage)))
            {
                throw record.Error($"category '{link.CategoryName}' holds no rate of {link.Percentage}");
            }

            // Agent.allCommissionRates (CommissionRatesByCategoryDict): one rate per category for each agent.
            if (links.Exists(existing => existing.AgentName == link.AgentName && existing.CategoryName == link.CategoryName))
            {
                throw record.Error($"agent '{link.AgentName}' already holds a '{link.CategoryName}' rate");
            }

            links.Add(link);
        }

        return links;
    }

    // loadTenders: offer, date, time, client, tender-item GUID (L8899-8909); TenderTA.doValidate (L13900-13945).
    private static IReadOnlyList<ExpectedTenderLine> LoadTenders(
        IReadOnlyList<DataRecord> records,
        IReadOnlyList<ExpectedItem> tenderItems,
        IReadOnlyList<ExpectedParty> clients,
        IReadOnlySet<string> closedItemGuids)
    {
        var itemsByGuid = tenderItems.ToDictionary(item => item.Guid, StringComparer.Ordinal);
        var clientNames = clients.Select(client => client.Name).ToHashSet(StringComparer.Ordinal);
        var timeOfferKeys = new HashSet<(DateOnly Date, TimeOnly Time, decimal Offer)>();
        var lines = new List<ExpectedTenderLine>();

        foreach (var record in records)
        {
            var offer = record.ReadDecimal(0);
            var date = record.ReadDate(1);
            var time = record.ReadTime(2);
            var clientName = record.Required(3);
            var itemGuid = record.Required(4);

            if (!itemsByGuid.TryGetValue(itemGuid, out var item))
            {
                throw record.Error($"tender item {itemGuid} does not exist");
            }

            if (!clientNames.Contains(clientName))
            {
                throw record.Error($"client '{clientName}' does not exist");
            }

            var persisted = !closedItemGuids.Contains(itemGuid);
            if (persisted)
            {
                if (offer <= 0m || offer < item.Price)
                {
                    throw record.Error($"offer {offer} is not greater than 0 and at least the reserve {item.Price}");
                }

                if (lines.Exists(line => line.Persisted && line.ItemGuid == itemGuid && line.ClientName == clientName && line.Offer == offer))
                {
                    throw record.Error($"client '{clientName}' already tendered {offer} on item {itemGuid}");
                }

                // TendersByTimeOfferDict on Company.allTenders: (dateTendered, offer) is unique company-wide.
                if (!timeOfferKeys.Add((date, time, offer)))
                {
                    throw record.Error($"another tender already holds time {date} {time} and offer {offer}");
                }
            }

            lines.Add(new ExpectedTenderLine(offer, date, time, clientName, itemGuid, persisted));
        }

        return lines;
    }

    // loadRetailSales: date, time, price, client, retail-item GUID (L8729-8738); SaleTA and RetailSaleTA validation.
    private static IReadOnlyList<ExpectedRetailSale> LoadRetailSales(
        IReadOnlyList<DataRecord> records,
        IReadOnlyList<ExpectedItem> retailItems,
        IReadOnlyList<ExpectedParty> clients,
        CommissionCalculator commissions)
    {
        var itemsByGuid = retailItems.ToDictionary(item => item.Guid, StringComparer.Ordinal);
        var clientNames = clients.Select(client => client.Name).ToHashSet(StringComparer.Ordinal);
        var soldItemGuids = new HashSet<string>(StringComparer.Ordinal);
        var sales = new List<ExpectedRetailSale>();

        foreach (var record in records)
        {
            var date = record.ReadDate(0);
            var time = record.ReadTime(1);
            var salePrice = record.ReadDecimal(2);
            var clientName = record.Required(3);
            var itemGuid = record.Required(4);

            if (!itemsByGuid.TryGetValue(itemGuid, out var item))
            {
                throw record.Error($"retail item {itemGuid} does not exist");
            }

            if (!clientNames.Contains(clientName))
            {
                throw record.Error($"client '{clientName}' does not exist");
            }

            if (salePrice <= 0m)
            {
                throw record.Error($"sale price {salePrice} is not greater than 0");
            }

            // SaleTA.doValidate: the item must be unsold on create (L12780-12820).
            if (!soldItemGuids.Add(itemGuid))
            {
                throw record.Error($"retail item {itemGuid} is already sold");
            }

            sales.Add(new ExpectedRetailSale(
                date, time, salePrice, clientName, itemGuid, commissions.Calculate(item, salePrice)));
        }

        return sales;
    }

    // Company.closeTendersAtDate at the current date (L6670-6708). allTenderItemsBySaleDate reversed orders unsold
    // items first, then closure date ascending, category prefix descending and code number descending; no tender
    // item is sold before the closure runs.
    private static (IReadOnlyList<ExpectedTenderSale> TenderSales, IReadOnlySet<string> DueItemGuids) CloseTenders(
        IReadOnlyList<ExpectedItem> tenderItems,
        IReadOnlyList<ExpectedTenderLine> tenderLines,
        IReadOnlyList<ExpectedCategory> categories,
        CommissionCalculator commissions)
    {
        var prefixes = categories.ToDictionary(category => category.Name, category => category.Prefix, StringComparer.Ordinal);
        var closureOrder = tenderItems
            .OrderBy(item => item.FileClosureDate)
            .ThenByDescending(item => prefixes[item.CategoryName], StringComparer.Ordinal)
            .ThenByDescending(item => item.CodeNumber);

        var tenderSales = new List<ExpectedTenderSale>();
        var dueItemGuids = new HashSet<string>(StringComparer.Ordinal);

        foreach (var item in closureOrder)
        {
            // The run stops at the first item whose closure date is after the closure date.
            if (item.FileClosureDate > OffsetStartDate)
            {
                break;
            }

            dueItemGuids.Add(item.Guid);

            // TenderItem.acceptHighestTender: first of allTendersByOfferTime, offer descending then time ascending (L7123-7160).
            var winner = tenderLines
                .Where(line => line.Persisted && line.ItemGuid == item.Guid)
                .OrderByDescending(line => line.Offer)
                .ThenBy(line => line.FileDate)
                .ThenBy(line => line.Time)
                .FirstOrDefault();
            if (winner is null)
            {
                continue;
            }

            // TenderSale.onCreate: commission on the winning offer (L7767).
            tenderSales.Add(new ExpectedTenderSale(
                item.Guid,
                winner.ClientName,
                winner.Offer,
                winner.FileDate,
                winner.Time,
                commissions.Calculate(item, winner.Offer)));
        }

        return (tenderSales, dueItemGuids);
    }

    // loadData read loop: each line trimBlanks; an empty line or a line starting with '#' is skipped.
    // File.ReadAllLines ends a line at CR, LF or CR LF and returns a last line that has no line end.
    private static IReadOnlyList<DataRecord> ReadRecords(
        string dataDirectory,
        string fileName,
        int tokenCount,
        Dictionary<string, int> lineCounts)
    {
        var path = Path.Combine(dataDirectory, fileName);
        var records = new List<DataRecord>();
        var lineNumber = 0;

        foreach (var rawLine in File.ReadAllLines(path, Encoding.Latin1))
        {
            lineNumber++;
            var line = rawLine.Trim(Blank);
            if (line.Length == 0 || line[0] == LineSkipDelimiter)
            {
                continue;
            }

            var record = new DataRecord(fileName, lineNumber, GetTokens(line));
            if (record.Tokens.Count != tokenCount)
            {
                throw record.Error($"expected {tokenCount} tokens, found {record.Tokens.Count}");
            }

            records.Add(record);
        }

        lineCounts[fileName] = records.Count;
        return records;
    }

    // getNextToken applied until the line is exhausted (L7982-8051): leading Tab and Space characters are skipped,
    // a token runs to the next Tab or the end of the line and is trimmed of spaces, the token "null" is null,
    // and the line ends when no characters remain.
    private static IReadOnlyList<string?> GetTokens(string line)
    {
        var tokens = new List<string?>();
        var index = 0;

        while (true)
        {
            while (index < line.Length && (line[index] == TokenSeparator || line[index] == Blank))
            {
                index++;
            }

            if (index >= line.Length)
            {
                return tokens;
            }

            var separator = line.IndexOf(TokenSeparator, index);
            var end = separator < 0 ? line.Length : separator;
            var token = line[index..end].Trim(Blank);
            tokens.Add(string.Equals(token, NullToken, StringComparison.Ordinal) ? null : token);
            index = end + 1;
        }
    }

    // One non-skipped data-file line and its tokens; conversions are culture-invariant.
    private sealed record DataRecord(string FileName, int LineNumber, IReadOnlyList<string?> Tokens)
    {
        public string? Optional(int column) => Tokens[column];

        public string Required(int column) =>
            Tokens[column] ?? throw Error($"column {column + 1} is null");

        // A Decimal[n, 2] assignment rounds to 2 places, ties away from zero.
        public decimal ReadDecimal(int column)
        {
            var token = Required(column);
            return decimal.TryParse(token, NumberStyles.Number, CultureInfo.InvariantCulture, out var value)
                ? DecimalRules.Round2(value)
                : throw Error($"column {column + 1} '{token}' is not a decimal");
        }

        public DateOnly ReadDate(int column)
        {
            var token = Required(column);
            return DateOnly.TryParseExact(
                token, DateFormats, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out var value)
                ? value
                : throw Error($"column {column + 1} '{token}' is not a date");
        }

        public TimeOnly ReadTime(int column)
        {
            var token = Required(column);
            return TimeOnly.TryParseExact(token, TimeFormat, CultureInfo.InvariantCulture, DateTimeStyles.None, out var value)
                ? value
                : throw Error($"column {column + 1} '{token}' is not a time");
        }

        public InvalidOperationException Error(string message) =>
            new($"{FileName} line {LineNumber}: {message}.");
    }

    // Item references: allAgents[name], getRegion(country, region) and allItemCategoriesByName[name] (L8654-8656, L8824-8826).
    private sealed class ItemReferences(
        IReadOnlyList<ExpectedParty> agents,
        IReadOnlyList<ExpectedRegion> regions,
        IReadOnlyList<ExpectedCategory> categories)
    {
        private readonly HashSet<string> agentNames = agents.Select(agent => agent.Name).ToHashSet(StringComparer.Ordinal);
        private readonly HashSet<ExpectedRegion> regionKeys = [.. regions];
        private readonly HashSet<string> categoryNames = categories.Select(category => category.Name).ToHashSet(StringComparer.Ordinal);

        public void EnsureResolved(DataRecord record, ExpectedItem item)
        {
            if (!agentNames.Contains(item.AgentName))
            {
                throw record.Error($"agent '{item.AgentName}' does not exist");
            }

            if (!regionKeys.Contains(new ExpectedRegion(item.CountryName, item.RegionName)))
            {
                throw record.Error($"region '{item.RegionName}' of country '{item.CountryName}' does not exist");
            }

            if (!categoryNames.Contains(item.CategoryName))
            {
                throw record.Error($"category '{item.CategoryName}' does not exist");
            }
        }
    }

    // Sale.calculateAgentCommission with Agent.getCommissionRateForCategory (L7528-7557, L6294-6335): the agent's rate
    // for the item's category, else the category's lowest rate (allCommissionRates.first()), else no commission.
    private sealed class CommissionCalculator(
        IReadOnlyList<ExpectedAgentRate> agentRates,
        IReadOnlyList<ExpectedCategoryRate> categoryRates)
    {
        public decimal Calculate(ExpectedItem item, decimal salePrice)
        {
            var percentage = agentRates
                .Where(rate => rate.AgentName == item.AgentName && rate.CategoryName == item.CategoryName)
                .Select(rate => (decimal?)rate.Percentage)
                .FirstOrDefault()
                ?? categoryRates
                    .Where(rate => rate.CategoryName == item.CategoryName)
                    .Select(rate => (decimal?)rate.Percentage)
                    .Min();

            return percentage is { } percent ? DecimalRules.Round2(salePrice * (percent / 100m)) : 0m;
        }
    }
}

/// <summary>The expected company: its name and address.</summary>
public sealed record ExpectedCompany(string Name, ExpectedAddress Address);

/// <summary>An expected embedded address; a JADE null string is <see langword="null"/>.</summary>
public sealed record ExpectedAddress(
    string Street,
    string City,
    string Country,
    string Email,
    string? Fax,
    string? Phone,
    string? WebSite);

/// <summary>An expected agent or client.</summary>
public sealed record ExpectedParty(string Name, ExpectedAddress Address);

/// <summary>An expected country and the names of its regions in load order.</summary>
public sealed record ExpectedCountry(string Name, IReadOnlyList<string> RegionNames);

/// <summary>An expected region of a country.</summary>
public sealed record ExpectedRegion(string CountryName, string Name);

/// <summary>An expected item category; the prefix is upper case.</summary>
public sealed record ExpectedCategory(string Prefix, string Name, string Description);

/// <summary>An expected category commission rate.</summary>
public sealed record ExpectedCategoryRate(string CategoryName, decimal Percentage);

/// <summary>An expected link between an agent and the category rate with the given percentage.</summary>
public sealed record ExpectedAgentRate(string AgentName, string CategoryName, decimal Percentage);

/// <summary>
/// An expected retail or tender item. <see cref="Price"/> is the retail price or the tender reserve; the file
/// dates are unshifted.
/// </summary>
public sealed record ExpectedItem(
    string Guid,
    bool IsTender,
    int CodeNumber,
    string Name,
    string Description,
    string? PhotoFileName,
    byte[]? PhotoBytes,
    decimal Price,
    DateOnly FileListedDate,
    DateOnly? FileClosureDate,
    string AgentName,
    string CountryName,
    string RegionName,
    string CategoryName)
{
    /// <summary>The listed date shifted by <paramref name="offsetDays"/>.</summary>
    public DateOnly ListedDate(int offsetDays) => FileListedDate.AddDays(offsetDays);

    /// <summary>The closure date shifted by <paramref name="offsetDays"/>; <see langword="null"/> for a retail item.</summary>
    public DateOnly? ClosureDate(int offsetDays) => FileClosureDate?.AddDays(offsetDays);
}

/// <summary>An expected <c>Tenders.txt</c> line and whether its tender persists.</summary>
public sealed record ExpectedTenderLine(
    decimal Offer,
    DateOnly FileDate,
    TimeOnly Time,
    string ClientName,
    string ItemGuid,
    bool Persisted)
{
    /// <summary>The tender timestamp: the file date shifted by <paramref name="offsetDays"/>, at the file time.</summary>
    public DateTime Timestamp(int offsetDays) => FileDate.AddDays(offsetDays).ToDateTime(Time);
}

/// <summary>An expected retail sale with its agent commission.</summary>
public sealed record ExpectedRetailSale(
    DateOnly FileDate,
    TimeOnly Time,
    decimal SalePrice,
    string ClientName,
    string ItemGuid,
    decimal AgentCommission)
{
    /// <summary>The sale timestamp: the file date shifted by <paramref name="offsetDays"/>, at the file time.</summary>
    public DateTime DateSold(int offsetDays) => FileDate.AddDays(offsetDays).ToDateTime(Time);
}

/// <summary>An expected tender sale: the winning tender of a closed item and the commission on its offer.</summary>
public sealed record ExpectedTenderSale(
    string ItemGuid,
    string ClientName,
    decimal Offer,
    DateOnly TenderFileDate,
    TimeOnly TenderTime,
    decimal AgentCommission)
{
    /// <summary>The winning tender's timestamp: its file date shifted by <paramref name="offsetDays"/>, at its file time.</summary>
    public DateTime TenderTimestamp(int offsetDays) => TenderFileDate.AddDays(offsetDays).ToDateTime(TenderTime);
}
